import { readFile,mkdir,writeFile } from 'node:fs/promises';
const target=new URL('../supabase/',import.meta.url);await mkdir(target,{recursive:true});
const files=['001_core.sql','003_integrations.sql','005_product_workflows.sql','006_push_delivery.sql','007_social_completion.sql','008_venue_applications.sql','009_multi_court_slots.sql','010_private_event_locations.sql','011_indexes_and_sync.sql','012_discovery_history.sql','013_upload_receipts.sql','014_identity_cleanup_history.sql','015_admin_system.sql','002_postgres_security.sql'];
const sections=await Promise.all(files.map(async name=>`-- ${name}\n${await readFile(new URL(`../migrations/${name}`,import.meta.url),'utf8')}`));
await writeFile(new URL('01_schema.sql',target),'-- Generated by npm run supabase:bundle. No demo users or secrets.\nBEGIN;\n'+sections.join('\n')+'\nCOMMIT;\n');
await writeFile(new URL('02_storage.sql',target),await readFile(new URL('../migrations/004_supabase_storage.sql',import.meta.url),'utf8'));
await writeFile(new URL('03_verify.sql',target),`-- Read-only verification; expected denied_mobile_grants = 0.
SELECT version,applied_at FROM public.schema_migrations ORDER BY version;
SELECT count(*) AS denied_mobile_grants FROM information_schema.table_privileges
 WHERE table_schema='public' AND grantee IN ('anon','authenticated')
 AND table_name IN (${[...sections.join('\n').matchAll(/CREATE TABLE IF NOT EXISTS (\w+)/g)].map(m=>`'${m[1]}'`).filter(v=>v!=="'schema_migrations'").join(',')});
SELECT id,public,file_size_limit,allowed_mime_types FROM storage.buckets WHERE id='matchora-private';
`);
console.log('Supabase SQL Editor files generated: backend/supabase/01_schema.sql, 02_storage.sql, 03_verify.sql');
